// One-time, owner-approved YouTube SEO metadata changes.
// No uploads, no changes to status/visibility, no autogenerated tags.
// Preflight: exact channel ID; public playlist contents; exact video titles;
// API readback and before/after snapshots for recovery.
import {mkdir,writeFile} from 'node:fs/promises';
import {legacyYouTubeAccessToken,verifySurrealOwner,SURREAL_ASMR_ID} from '../src/auth.mjs';

const PLAYLIST_ID='PLcvQlecwMwmo';
const PLAYLIST_URL='https://www.youtube.com/playlist?list='+PLAYLIST_ID;
const WATER='YQByazV5lWU', RAIN='fn_pI5rHo6c', SAND='FgUS9hMYEbk';
const SAND_OLD='Three calming sand-pouring textures, close-up visuals and crisp recorded sand sounds. Best enjoyed w';
const SAND_NEW='Sand Pouring ASMR | Three Satisfying Textures & Crisp Sand Sounds';
const WATER_TITLE='10 Minutes of Water ASMR 💧 Relaxing Stream & Waterfall Sounds';
const RAIN_TITLE='Rain ASMR 🌧️ Relaxing Rain on Glass & Night Sounds #Shorts';
const playlistNote='Continue with Water & Rain ASMR: '+PLAYLIST_URL;
const wantedIds=[SAND,WATER,RAIN];
const token=await legacyYouTubeAccessToken();
await verifySurrealOwner(token);
console.log('ASMR_METADATA_OWNER_VERIFIED',SURREAL_ASMR_ID);

async function call(resource,{method='GET',query={},body}={}){
 const url=new URL('https://www.googleapis.com/youtube/v3/'+resource);
 for(const [k,v] of Object.entries(query))url.searchParams.set(k,String(v));
 const r=await fetch(url,{
  method,headers:{Authorization:'Bearer '+token,...(body?{'Content-Type':'application/json'}:{})},
  ...(body?{body:JSON.stringify(body)}:{}),signal:AbortSignal.timeout(15000)
 });
 const j=await r.json().catch(()=>({}));
 if(!r.ok){
  const reason=j?.error?.errors?.[0]?.reason||j?.error?.status||'unknown';
  throw new Error('YouTube '+resource+' '+method+' failed HTTP '+r.status+' ('+reason+')');
 }
 return j;
}
function ensure(condition,message){if(!condition)throw new Error(message)}
function snippetBody(s,title,description){
 const v={title,description,categoryId:s.categoryId};
 if(s.defaultLanguage)v.defaultLanguage=s.defaultLanguage;
 if(s.tags!==undefined)v.tags=s.tags;
 return v;
}
function addPlaylist(description){
 if(description.includes(PLAYLIST_URL))return description;
 const boundary=description.lastIndexOf('\n\n#');
 return boundary>=0
  ?description.slice(0,boundary)+'\n\n'+playlistNote+description.slice(boundary)
  :description+'\n\n'+playlistNote;
}
function simplify(v){
 return {id:v.id,title:v.snippet.title,description:v.snippet.description,
   categoryId:v.snippet.categoryId,tags:v.snippet.tags||[],
   defaultLanguage:v.snippet.defaultLanguage||null,
   privacyStatus:v.status?.privacyStatus};
}
async function readVideos(ids){
 const x=await call('videos',{query:{part:'snippet,status',id:ids.join(',')}});
 ensure((x.items||[]).length===ids.length,'Not all expected owned videos are accessible');
 const map=new Map((x.items||[]).map(v=>[v.id,v]));
 for(const id of ids)ensure(map.get(id)?.snippet?.channelId===SURREAL_ASMR_ID,'Video '+id+' does not match Surreal ASMR channel ID');
 return map;
}

await mkdir('audit-output',{recursive:true});
const playlist=await call('playlists',{query:{part:'id,snippet,status',id:PLAYLIST_ID}});
ensure(playlist.items?.[0]?.snippet?.channelId===SURREAL_ASMR_ID &&
 playlist.items?.[0]?.status?.privacyStatus==='public' &&
 playlist.items?.[0]?.snippet?.title==='Water & Rain ASMR','Playlist identity/visibility mismatch; no metadata writes');
const members=await call('playlistItems',{query:{part:'contentDetails',playlistId:PLAYLIST_ID,maxResults:50}});
const memberIds=new Set((members.items||[]).map(x=>x.contentDetails?.videoId));
ensure(memberIds.has(WATER)&&memberIds.has(RAIN),'Water and rain videos not both confirmed in playlist; no metadata writes');

const current=await readVideos(wantedIds);
const sand=current.get(SAND).snippet;
const water=current.get(WATER).snippet;
const rain=current.get(RAIN).snippet;
ensure(sand.title===SAND_OLD||sand.title===SAND_NEW,'Sand title changed since owner-reviewed snapshot; stop before updates');
ensure(water.title===WATER_TITLE,'Water title changed since snapshot; stop before updates');
ensure(rain.title===RAIN_TITLE,'Rain title changed since snapshot; stop before updates');
for(const id of wantedIds)ensure(current.get(id).status?.privacyStatus==='public','Selected video visibility changed; no metadata writes');

const expected={
 [SAND]:snippetBody(sand,SAND_NEW,sand.description),
 [WATER]:snippetBody(water,water.title,addPlaylist(water.description)),
 [RAIN]:snippetBody(rain,rain.title,addPlaylist(rain.description))
};
for(const [id,desired] of Object.entries(expected)){
 ensure(desired.title.length<=100&&new TextEncoder().encode(desired.description).length<=5000,'Invalid YouTube text length for '+id);
 ensure(desired.categoryId,'Missing category ID for '+id);
}
const snapshot={
 channelId:SURREAL_ASMR_ID,playlistId:PLAYLIST_ID,
 inspectedAt:new Date().toISOString(),
 before:wantedIds.map(id=>simplify(current.get(id))),
 expected:wantedIds.map(id=>({id,...expected[id]})),
 results:[]
};
await writeFile('audit-output/surreal-asmr-metadata-change.json',JSON.stringify(snapshot,null,2)+'\n');
for(const id of wantedIds){
 const old=simplify(current.get(id));
 const desired=expected[id];
 if(old.title===desired.title&&old.description===desired.description){
  snapshot.results.push({id,outcome:'already-correct'});
  console.log('ASMR_METADATA_ALREADY_CORRECT',id);
  continue;
 }
 console.log('ASMR_METADATA_CHANGE_REQUEST',id, 'title_changed='+(old.title!==desired.title),
             'description_playlist_link_added='+(old.description!==desired.description));
 await call('videos',{method:'PUT',query:{part:'snippet'},body:{id,snippet:desired}});
 let after;
 for(let attempt=0;attempt<5;attempt++){
  const map=await readVideos([id]);
  after=simplify(map.get(id));
  if(after.title===desired.title&&after.description===desired.description)break;
  await new Promise(resolve=>setTimeout(resolve,600*(attempt+1)));
 }
 ensure(after.title===desired.title&&after.description===desired.description,'YouTube returned success but metadata readback differs for '+id);
 ensure(after.privacyStatus===old.privacyStatus&&after.categoryId===old.categoryId,
  'Unexpected privacy/category drift detected after update to '+id);
 ensure(JSON.stringify(after.tags)===JSON.stringify(old.tags),'Unexpected tag drift after update to '+id);
 snapshot.results.push({id,outcome:'changed-and-verified',before:old,after});
 await writeFile('audit-output/surreal-asmr-metadata-change.json',JSON.stringify(snapshot,null,2)+'\n');
 console.log('ASMR_METADATA_VERIFIED',id,'title='+after.title,'playlist_link='+(after.description.includes(PLAYLIST_URL)));
}
console.log('ASMR_METADATA_ALL_FINISHED',JSON.stringify(snapshot.results.map(x=>({id:x.id,outcome:x.outcome}))));
